const svgColorCache = new Map<string, string>();

function decodeBase64(b64: string): string {
  const cleanB64 = b64.replace(/\s+/g, '');
  if (typeof atob === 'function') {
    try {
      return decodeURIComponent(escape(atob(cleanB64)));
    } catch (_e) {
      try {
        return atob(cleanB64);
      } catch (_e2) {}
    }
  }
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  let str = '';
  let i = 0;
  const filteredB64 = cleanB64.replace(/[^A-Za-z0-9+/=]/g, '');
  while (i < filteredB64.length) {
    const enc1 = chars.indexOf(filteredB64.charAt(i++));
    const enc2 = chars.indexOf(filteredB64.charAt(i++));
    const enc3 = chars.indexOf(filteredB64.charAt(i++));
    const enc4 = chars.indexOf(filteredB64.charAt(i++));
    const chr1 = (enc1 << 2) | (enc2 >> 4);
    const chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
    const chr3 = ((enc3 & 3) << 6) | enc4;
    str += String.fromCharCode(chr1);
    if (enc3 !== 64 && enc3 !== -1) str += String.fromCharCode(chr2);
    if (enc4 !== 64 && enc4 !== -1) str += String.fromCharCode(chr3);
  }
  return str;
}

function encodeBase64(input: string): string {
  if (typeof btoa === 'function') {
    try {
      return btoa(unescape(encodeURIComponent(input)));
    } catch (_e) {}
  }
  const maybeBuffer = (globalThis as any).Buffer;
  if (typeof maybeBuffer !== 'undefined' && typeof maybeBuffer.from === 'function') {
    try {
      return maybeBuffer.from(input, 'utf8').toString('base64');
    } catch (_e) {}
  }
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  const utf8Str = unescape(encodeURIComponent(input));
  let output = '';
  for (let i = 0; i < utf8Str.length; i += 3) {
    const c1 = utf8Str.charCodeAt(i);
    const c2 = i + 1 < utf8Str.length ? utf8Str.charCodeAt(i + 1) : NaN;
    const c3 = i + 2 < utf8Str.length ? utf8Str.charCodeAt(i + 2) : NaN;

    const e1 = c1 >> 2;
    const e2 = ((c1 & 3) << 4) | (isNaN(c2) ? 0 : c2 >> 4);
    const e3 = isNaN(c2) ? 64 : ((c2 & 15) << 2) | (isNaN(c3) ? 0 : c3 >> 6);
    const e4 = isNaN(c2) || isNaN(c3) ? 64 : c3 & 63;

    output += chars.charAt(e1) + chars.charAt(e2) + chars.charAt(e3) + chars.charAt(e4);
  }
  return output;
}

export function getColoredSvgUri(rawUri: string, color: string): string {
  if (!rawUri || !color) return rawUri;
  const cacheKey = `${color}__${rawUri}`;
  const cached = svgColorCache.get(cacheKey);
  if (cached) return cached;

  try {
    let xml = '';
    if (rawUri.startsWith('data:image/svg+xml;base64,')) {
      const b64 = rawUri.replace('data:image/svg+xml;base64,', '');
      xml = decodeBase64(b64);
    } else if (rawUri.startsWith('data:image/svg+xml;utf8,')) {
      xml = decodeURIComponent(rawUri.replace('data:image/svg+xml;utf8,', ''));
    } else if (rawUri.startsWith('<svg')) {
      xml = rawUri;
    } else {
      return rawUri;
    }

    // Ensure root <svg> has real width and height attributes (not just stroke-width)
    const hasRealWidth = /<svg[^>]*\s+width=["'][^"']+["']/.test(xml);
    const hasRealHeight = /<svg[^>]*\s+height=["'][^"']+["']/.test(xml);
    if (!hasRealWidth || !hasRealHeight) {
      const vbMatch = xml.match(/viewBox=["']([0-9.\s-]+)["']/);
      let w = '24';
      let h = '24';
      if (vbMatch) {
        const parts = vbMatch[1].trim().split(/\s+/);
        if (parts.length === 4) {
          w = parts[2];
          h = parts[3];
        }
      }
      if (!hasRealWidth && !hasRealHeight) {
        xml = xml.replace(/<svg\b/, `<svg width="${w}" height="${h}"`);
      } else if (!hasRealWidth) {
        xml = xml.replace(/<svg\b/, `<svg width="${w}"`);
      } else if (!hasRealHeight) {
        xml = xml.replace(/<svg\b/, `<svg height="${h}"`);
      }
    }

    const hasStroke = /stroke=["'](?!none)[^"']+["']/.test(xml);
    const hasFill = /fill=["'](?!none)[^"']+["']/.test(xml);

    if (hasStroke) {
      xml = xml.replace(/stroke=["'](?!none)[^"']*["']/g, `stroke="${color}"`);
    }
    if (hasFill) {
      xml = xml.replace(/fill=["'](?!none)[^"']*["']/g, `fill="${color}"`);
    }
    if (!hasStroke && !hasFill) {
      xml = xml.replace(/<svg\b/, `<svg stroke="${color}" fill="none"`);
    }

    const result = `data:image/svg+xml;base64,${encodeBase64(xml)}`;
    svgColorCache.set(cacheKey, result);
    return result;
  } catch (_e) {
    return rawUri;
  }
}


